export function analyzeGroove(p){if(!Number.isFinite(p.bpm)||p.bpm<=0||!Array.isArray(p.tracks))throw Error('Session invalide');const voices=new Map();for(const t of p.tracks){if(t.mute)continue;for(const c of t.clips||[]){if(c.muted||!Number.isFinite(c.start))continue;for(const [name,row] of Object.entries(c.pattern||{})){if(!Array.isArray(row))continue;const hits=voices.get(name)||[];row.forEach((v,i)=>{if(Number.isFinite(v)&&v>0)hits.push({step:c.start*16+i,velocity:v})});voices.set(name,hits);}}}return {bpm:p.bpm,stepMilliseconds:60000/p.bpm/4,voices:[...voices].map(([name,hits])=>{hits.sort((a,b)=>a.step-b.step);const grid=Array(16).fill(0);for(const h of hits)grid[((Math.round(h.step)%16)+16)%16]++;return {name,hits:hits.length,grid,offbeatFraction:hits.length?hits.filter(h=>Math.round(h.step)%4!==0).length/hits.length:null,meanVelocity:hits.length?hits.reduce((a,h)=>a+h.velocity,0)/hits.length:null};}),limitations:['16-step 4/4 pattern model; no automatic genre classification or performed swing estimation.']};}